 17	const POINT = { x: 20_000, y: 30_000 };
 18	const config = createClaimConfig({ claimPoint: POINT });
 19	const CHANNEL = config.channelTicks;
 20	const RADIUS = config.circleRadius;
 21	
 22	/** A player who could claim: at the claim point, stopped, holding everything, connected, unprotected. */
 23	function player(id: string, change: Partial<ClaimPlayer> = {}): ClaimPlayer {
 24	  return { id, x: POINT.x, y: POINT.y, speed: 0, holdsAllTypes: true, interact: true, connected: true, protected: false, ...change };
 25	}
 26	
 27	function duel(id: string, a: string, b: string): ClaimEncounter {
 28	  return { id, playerIds: [a, b] };
 29	}
 30	
 31	/** Recursively frozen, so a step that mutated its input would throw. */
 32	function deepFreeze<T>(value: T): T {
 33	  if (typeof value === "object" && value !== null && !Object.isFrozen(value)) {
 34	    Object.freeze(value);
 35	    for (const child of Object.values(value)) deepFreeze(child);
 36	  }
 37	  return value;
 38	}
 39	
 40	type Tick = { players: ClaimPlayer[]; encounters?: ClaimEncounter[] };
 41	
 42	/** Steps one tick with frozen input and state, checking neither is changed. */
 43	function step(state: ClaimState, tick: Tick, cfg: ClaimConfig = config) {
 44	  const input: ClaimTickInput = deepFreeze({ tick: state.tick + 1, players: tick.players, encounters: tick.encounters ?? [] });
 45	  const before = hashState(deepFreeze(state));
 46	  const stepped = stepClaim(cfg, state, input);
 47	  expect(hashState(state)).toBe(before);
 48	  return stepped;
 49	}
 50	
 51	/** Steps `count` identical ticks and returns the final state and every event. */
 52	function hold(state: ClaimState, tick: Tick, count: number, cfg: ClaimConfig = config) {
 53	  const events: ClaimEvent[] = [];
 54	  let current = state;
 55	  for (let index = 0; index < count; index++) {
 56	    const stepped = step(current, tick, cfg);
 57	    current = stepped.state;
 58	    events.push(...stepped.events);
 59	  }
 60	  return { state: current, events };
 61	}
 62	
 63	const kinds = (events: readonly ClaimEvent[]) => events.map((event) => event.kind);
 64	
 65	describe("claim config", () => {
 66	  it("uses the content rules: a 200-tick channel, the treasure circle in sub-units and the minute-35 deadline", () => {
 67	    expect(config).toEqual({ claimPoint: POINT, circleRadius: claimRules.circleRadiusTiles * 256, channelTicks: 200, deadlineTick: 42_000 });
 68	    expect(createClaimConfig({ claimPoint: POINT, controlStartTick: 60 }).deadlineTick).toBe(42_060);
 69	    expect(() => createClaimConfig({ claimPoint: POINT, rules: { ...claimRules, channelTicks: -1 } })).toThrow(/invalid claim rules/);
 70	    expect(() => createClaimConfig({ claimPoint: { x: 0.5, y: 0 } })).toThrow(RangeError);
 71	    expect(() => createClaimState(config, config.deadlineTick)).toThrow(RangeError);
 72	    expect(createClaimState(config)).toEqual({ tick: 0, channel: null, result: null });
 73	  });
 74	});
 75	
 76	describe("eligibility (§5)", () => {
 77	  const start = createClaimState(config);
 78	
 79	  it("lets a player start who holds all four types inside the circle, stopped, connected and holding interact", () => {
 80	    const { state, events } = step(start, { players: [player("a")] });
 81	    expect(events).toEqual([{ kind: "claim-started", tick: 1, playerId: "a" }]);
 82	    expect(state.channel).toEqual({ playerId: "a", startTick: 1, x: POINT.x, y: POINT.y, progress: 0 });
 83	  });
 84	
 85	  it("counts the circle's edge as inside and one sub-unit beyond it as outside", () => {
 86	    expect(step(start, { players: [player("a", { x: POINT.x + RADIUS })] }).state.channel?.playerId).toBe("a");
 87	    expect(step(start, { players: [player("a", { y: POINT.y - RADIUS })] }).state.channel?.playerId).toBe("a");
 88	    expect(step(start, { players: [player("a", { x: POINT.x + RADIUS + 1 })] }).state.channel).toBeNull();
 89	    // (3r/5, 4r/5) lies exactly on the circle when r is a multiple of 5; one sub-unit further does not.
 90	    const r = RADIUS - (RADIUS % 5);
 91	    const edge = createClaimConfig({ claimPoint: POINT, rules: { ...claimRules, circleRadiusTiles: 5 }, subUnitsPerTile: r / 5 });
 92	    expect(step(start, { players: [player("a", { x: POINT.x + (3 * r) / 5, y: POINT.y + (4 * r) / 5 })] }, edge).state.channel).not.toBeNull();
 93	    expect(step(start, { players: [player("a", { x: POINT.x + (3 * r) / 5 + 1, y: POINT.y + (4 * r) / 5 })] }, edge).state.channel).toBeNull();
 94	  });
