105	    expect(state.channel).toBeNull();
106	    expect(events).toEqual([]);
107	  });
108	
109	  it("refuses a player reserved for a duel", () => {
110	    const { state, events } = step(start, { players: [player("a"), player("b", { interact: false })], encounters: [duel("e1", "a", "b")] });
111	    expect(state.channel).toBeNull();
112	    expect(events).toEqual([]);
113	  });
