116	    const { state, events } = step(start, { players: [player("a", { protected: true })] });
117	    expect(events).toEqual([
118	      { kind: "protection-ended", tick: 1, playerId: "a" },
119	      { kind: "claim-started", tick: 1, playerId: "a" },
120	    ]);
121	    expect(state.channel?.playerId).toBe("a");
122	  });
