    22	  });
    23	
    24	  it("refuse fractional, negative or missing durations, a bad radius and unknown fields", () => {
    25	    expect(issuesOf({ ...claimRules, channelTicks: 1.5 })[0]).toMatch(/^channelTicks:/);
    26	    expect(issuesOf({ ...claimRules, channelTicks: -1 })[0]).toMatch(/^channelTicks:/);
    27	    expect(issuesOf({ ...claimRules, deadlineTicks: 0 })[0]).toMatch(/^deadlineTicks:/);
    28	    expect(issuesOf({ ...claimRules, circleRadiusTiles: 0 })[0]).toMatch(/^circleRadiusTiles:/);
    29	    expect(issuesOf({ channelTicks: 200, deadlineTicks: 42_000 })[0]).toMatch(/^circleRadiusTiles:/);
    30	    expect(issuesOf({ ...claimRules, extra: 1 })).toHaveLength(1);
    31	  });
    32	
    33	  it("refuse a channel that could never complete before the deadline", () => {
    34	    expect(issuesOf({ ...claimRules, channelTicks: 42_000 })).toEqual([
    35	      "channelTicks: a channel of 42000 ticks cannot complete before the deadline (42000 ticks)",
    36	    ]);
