  1	import { claimRules } from "@pirate-sea-race/content/claim";
  2	import { describe, expect, it } from "vitest";
  3	import { nextInt } from "../random.js";
  4	import {
  5	  canStartClaim,
  6	  claimDistanceSquared,
  7	  createClaimConfig,
  8	  createClaimState,
  9	  hashState,
 10	  stepClaim,
 11	  type ClaimConfig,
 12	  type ClaimEncounter,
 13	  type ClaimEvent,
 14	  type ClaimPlayer,
 15	  type ClaimState,
 16	  type ClaimTickInput,
 17	} from "./index.js";
 18	
 19	const POINT = { x: 20_000, y: 30_000 };
 20	/** A short match with a short channel, so random ticks produce wins, interrupts and timeouts. */
 21	const config = createClaimConfig({ claimPoint: POINT, rules: { ...claimRules, channelTicks: 30, deadlineTicks: 400 } });
 22	
 23	/** Ids whose code-unit order differs from numeric and case-insensitive order. */
 24	const IDS = ["p1", "p10", "p2", "P3", "a", "B", "crew", "Z9"];
 25	/** Offsets from the claim point: several at the same distance (300), the circle's edge (1024) and outside it. */
 26	const SPOTS: readonly (readonly [number, number])[] = [
 27	  [0, 0],
 28	  [300, 0],
 29	  [0, 300],
 30	  [-300, 0],
 31	  [180, -240],
 32	  [500, 500],
 33	  [1024, 0],
 34	  [0, -1024],
 35	  [1025, 0],
 36	  [2000, 2000],
 37	];
 38	
 39	type Draw = (bound: number) => number;
 40	
 41	function generator(seed: number): Draw {
 42	  let rng = seed;
 43	  return (bound) => {
 44	    const drawn = nextInt(rng, bound);
 45	    rng = drawn.state;
 46	    return drawn.value;
 47	  };
 48	}
 49	
 50	function shuffled<T>(items: readonly T[], draw: Draw): T[] {
 51	  const copy = [...items];
 52	  for (let index = copy.length - 1; index > 0; index--) {
 53	    const other = draw(index + 1);
 54	    [copy[index], copy[other]] = [copy[other]!, copy[index]!];
 55	  }
 56	  return copy;
 57	}
 58	
 59	/**
 60	 * A seeded script of ticks from `start + 1` to past the deadline: players wander between spots, gain and lose their
 61	 * set, press and release interact, disconnect, gain protection, and pair off into duels that later end. `calm` (per
 62	 * mille) scales how rarely anything changes, so some scripts let a channel run to completion.
 63	 */
 64	function randomScript(seed: number, start: number, calm: number): ClaimTickInput[] {
 65	  const draw = generator(seed);
 66	  const chance = (perMille: number) => draw(1000) < Math.floor((perMille * (1000 - calm)) / 1000);
 67	  const count = 2 + draw(5);
 68	  const ids = shuffled(IDS, draw).slice(0, count);
 69	  const players = new Map<string, ClaimPlayer>();
 70	  for (const id of ids) {
 71	    const [dx, dy] = SPOTS[draw(SPOTS.length)]!;
 72	    players.set(id, { id, x: POINT.x + dx, y: POINT.y + dy, speed: 0, holdsAllTypes: draw(4) > 0, interact: draw(2) === 0, connected: true, protected: draw(3) === 0 });
 73	  }
 74	  let encounters: ClaimEncounter[] = [];
 75	  let encounterCount = 0;
 76	  const script: ClaimTickInput[] = [];
 77	  for (let tick = start + 1; tick <= config.deadlineTick + 20; tick++) {
 78	    for (const id of ids) {
 79	      let next = players.get(id)!;
 80	      if (next.speed !== 0) next = { ...next, speed: 0 };
 81	      if (chance(40)) {
 82	        const [dx, dy] = SPOTS[draw(SPOTS.length)]!;
 83	        next = { ...next, x: POINT.x + dx, y: POINT.y + dy, speed: 1 + draw(64) };
 84	      }
 85	      if (chance(20)) next = { ...next, holdsAllTypes: !next.holdsAllTypes };
 86	      if (chance(60)) next = { ...next, interact: !next.interact };
 87	      if (chance(15)) next = { ...next, connected: !next.connected };
 88	      if (chance(10)) next = { ...next, protected: !next.protected };
 89	      players.set(id, next);
 90	    }
 91	    encounters = encounters.filter(() => !chance(80));
 92	    if (chance(60)) {
 93	      const reserved = new Set(encounters.flatMap((encounter) => encounter.playerIds));
 94	      const free = ids.filter((id) => !reserved.has(id));
 95	      if (free.length >= 2) {
 96	        const [a, b] = shuffled(free, draw);
 97	        encounters = [...encounters, { id: `e${encounterCount++}`, playerIds: [a!, b!] }];
 98	      }
 99	    }
100	    // Now and then a player drops out of the snapshot altogether.
101	    const present = ids.filter(() => !chance(10));
102	    script.push({ tick, players: present.map((id) => players.get(id)!), encounters });
103	  }
104	  return script;
105	}
106	
107	interface Run {
108	  readonly states: readonly ClaimState[];
109	  readonly hashes: readonly string[];
110	  readonly events: readonly (readonly ClaimEvent[])[];
111	}
112	
113	function run(cfg: ClaimConfig, start: ClaimState, script: readonly ClaimTickInput[]): Run {
114	  const states: ClaimState[] = [];
115	  const events: ClaimEvent[][] = [];
116	  let state = start;
117	  for (const input of script) {
118	    const stepped = stepClaim(cfg, state, input);
119	    state = stepped.state;
120	    states.push(state);
121	    events.push([...stepped.events]);
122	  }
123	  return { states, hashes: states.map(hashState), events };
124	}
125	
126	/** The same script with every tick's players and encounters in a different order. */
127	function reorder(script: readonly ClaimTickInput[], seed: number): ClaimTickInput[] {
128	  const draw = generator(seed);
129	  return script.map((input) => ({ ...input, players: shuffled(input.players, draw), encounters: shuffled(input.encounters, draw) }));
130	}
131	
132	/** The same script with ids renamed and positions moved by a distance-preserving map about the claim point. */
133	function transform(
134	  script: readonly ClaimTickInput[],
135	  rename: (id: string) => string,
136	  move: (dx: number, dy: number) => readonly [number, number],
137	): ClaimTickInput[] {
138	  return script.map((input) => ({
139	    tick: input.tick,
140	    players: input.players.map((player) => {
141	      const [dx, dy] = move(player.x - POINT.x, player.y - POINT.y);
142	      return { ...player, id: rename(player.id), x: POINT.x + dx, y: POINT.y + dy };
143	    }),
144	    encounters: input.encounters.map((encounter) => ({
145	      id: encounter.id,
146	      playerIds: [rename(encounter.playerIds[0]), rename(encounter.playerIds[1])] as const,
147	    })),
148	  }));
149	}
150	
151	function renameEvents(events: readonly (readonly ClaimEvent[])[], rename: (id: string) => string): ClaimEvent[][] {
152	  return events.map((tick) =>
153	    tick.map((event) => {
154	      switch (event.kind) {
155	        case "duel-ended-without-theft":
156	          return { ...event, playerIds: [rename(event.playerIds[0]), rename(event.playerIds[1])] as const };
157	        case "match-ended":
158	          return { ...event, winner: event.winner === null ? null : rename(event.winner) };
159	        default:
160	          return { ...event, playerId: rename(event.playerId) };
161	      }
162	    }),
163	  );
164	}
165	
166	const SEEDS = Array.from({ length: 60 }, (_, index) => index + 1);
167	const scriptFor = (seed: number) => randomScript(seed, 0, [0, 500, 800][seed % 3]!);
168	
169	describe("seeded random ticks (§19 Endgame)", () => {
170	  it.each(SEEDS)("seed %i commits at most one winner, freezes after the result and keeps every invariant", (seed) => {
171	    const script = scriptFor(seed);
172	    const { states, hashes, events } = run(config, createClaimState(config), script);
173	    const all = events.flat();
174	    const completed = all.filter((event) => event.kind === "claim-completed");
175	    const ended = all.filter((event) => event.kind === "match-ended");
176	    expect(completed.length).toBeLessThanOrEqual(1);
177	    expect(ended).toHaveLength(1);
178	
179	    const resolvedAt = states.findIndex((state) => state.result !== null);
180	    expect(resolvedAt).toBeGreaterThanOrEqual(0);
181	    const result = states[resolvedAt]!.result!;
182	    expect(ended[0]).toMatchObject({ tick: result.tick, reason: result.reason, winner: result.winner });
183	    if (completed.length === 1) {
184	      expect(result).toEqual({ reason: "claim", winner: completed[0]!.playerId, tick: completed[0]!.tick });
185	    } else {
186	      expect(result).toEqual({ reason: "deadline", winner: null, tick: config.deadlineTick });
187	    }
188	    // After the result nothing changes, whatever arrives.
189	    for (let index = resolvedAt + 1; index < states.length; index++) {
190	      expect(states[index]).toBe(states[resolvedAt]);
191	      expect(hashes[index]).toBe(hashes[resolvedAt]);
192	      expect(events[index]).toEqual([]);
193	    }
194	
195	    for (let index = 0; index < resolvedAt; index++) {
196	      const input = script[index]!;
197	      const state = states[index]!;
198	      const reserved = new Set(input.encounters.flatMap((encounter) => encounter.playerIds));
199	      const channel = state.channel;
200	      if (channel !== null) {
201	        // The channeller is eligible this tick, where the channel started, and short of completion.
202	        const player = input.players.find((candidate) => candidate.id === channel.playerId);
203	        expect(player).toBeDefined();
204	        expect(canStartClaim(config, player!, reserved.has(player!.id))).toBe(true);
205	        expect([player!.x, player!.y]).toEqual([channel.x, channel.y]);
206	        expect(channel.progress).toBe(input.tick - channel.startTick);
